import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,T as l,b as u,k as d,l as f,n as p,o as m,p as h,t as g,w as _,x as v}from"./shared-BLp3PbbW.js";import{t as y}from"./file-text-z34ItJdM.js";import{t as b}from"./trophy--x7cj_yy.js";import{t as x}from"./CodeEditor-DqHMt3P8.js";var S=e();function C({module:e}){return(0,S.jsxs)(a,{children:[(0,S.jsx)(i,{variant:`project`,chip:e??`Блок 12 · Проверяемая передача`,title:`README и проверенная версия`,intro:`Проверим инструкции для Planner API в чистой копии и закрепим локальную версию за тем commit, который действительно удалось повторить.`,tags:[{icon:(0,S.jsx)(y,{size:14}),label:`README и передача`},{icon:(0,S.jsx)(b,{size:14}),label:`версия по фактам`}]}),(0,S.jsxs)(s,{number:`00`,title:`Передаём проект без догадок`,children:[(0,S.jsx)(o,{children:`Представим, что другой ученик скачал Planner API и впервые открыл папку. Сможет ли он запустить проект только по README?`}),(0,S.jsx)(d,{variant:`connected`,items:[{title:`Вход`,description:`Нужно сначала найти SHA и фактические результаты чистой проверки проекта.`},{title:`Действие`,description:`Исправить README и самим выполнить его команды с нуля.`},{title:`Выход`,description:`Локальный API-тег ведёт на проверенный commit с README.`}]}),(0,S.jsx)(`p`,{children:`README.md лежит в корне проекта и объясняет, что это за программа, как её установить и запустить. Хороший README не требует автора рядом: человек выполняет команды в указанном порядке, видит ожидаемый результат и понимает ограничения. Сейчас задача именно в такой инструкции, а не в разработке новых функций.`}),(0,S.jsx)(`p`,{children:`Чистая установка проекта должен был дать чистую проверку проекта. Но пока мы не увидели запись с результатами, считать её пройденной нельзя. Поэтому начнём с доказательств, затем исправим инструкцию, повторим её в отдельной чистой копии и только после этого поставим локальную метку версии. Так глава 4 получит понятный стартовый проект.`})]}),(0,S.jsxs)(s,{number:`01`,title:`Находим исходную проверенную версию`,children:[(0,S.jsx)(o,{children:`Прежде чем доверять записи об успешных тестах, выясним, к каким файлам она относится.`}),(0,S.jsx)(`p`,{children:`Git хранит проект в commit: это сохранённый снимок файлов. У снимка есть SHA, длинный уникальный идентификатор. Checkout означает, что мы открыли файлы выбранного commit. Чистым называем checkout без собственных незакоммиченных изменений. Так мы отличаем исходную проверенную версию от более поздних правок.`}),(0,S.jsx)(`p`,{children:`Откроем STUDYHUB_LEARNINGS.md и найдём именно результат чистой проверки проекта, а не старую запись с похожим описанием. Выпишем полный SHA, версию Python, команды установки, фактический итог pytest и отдельно результаты запуска CLI, API и Postman. Если чего-то не проверяли, ставим «не проверено». Пока записи этой проверки нет, у нас нет оснований объявить вход подтверждённым или создавать тег. Как удостовериться, что открыта та самая копия? Посмотрим на две команды.`}),(0,S.jsx)(x,{caption:`Запускаем из корня копии Planner`,code:`git rev-parse HEAD
git status --short`}),(0,S.jsx)(`p`,{children:`Первая команда показывает полный SHA текущего commit. Вторая перечисляет изменённые и новые файлы; пустой вывод означает, что рабочая копия чистая. Сверяем SHA с журналом чистой проверки проекта. Если он другой или есть изменения, сначала выясняем причину, иначе результаты тестов могут относиться к иным файлам.`}),(0,S.jsx)(t,{rows:[[`Состояние`,`Полный SHA, чистота checkout и версия Python`],[`Установка и тесты`,`Выполненные команды, их вывод и итог pytest`],[`Ручная проверка`,`Отдельные факты для CLI, запущенного API и Postman`]]}),(0,S.jsx)(`p`,{children:`Это похоже на этикетку образца в лаборатории: номер помогает связать результаты именно с тем образцом, который испытывали. Но этикетка не заменяет само испытание. Поэтому рядом с SHA храним и команду, и наблюдаемый результат, а не только фразу «всё работает».`}),(0,S.jsx)(`p`,{children:`pytest выполняет автоматические тесты. TestClient позволяет тестам обращаться к FastAPI внутри Python, без отдельного сервера. Uvicorn запускает сервер, который принимает настоящие HTTP-запросы. Postman отправляет подготовленные запросы вручную. Успех одного способа не подтверждает остальные. Числа 134 и 135 тестов встречаются в истории разных commit, поэтому в README нельзя переносить их без фактического запуска на нужном SHA.`}),(0,S.jsx)(c,{statement:`Если pytest прошёл с TestClient, то Uvicorn тоже точно запускался и отвечал на запросы.`,isTrue:!1,explanation:`TestClient обращается к приложению без сетевого запуска Uvicorn. Чтобы подтвердить реальный сервер, запускаем его отдельно, отправляем HTTP-запрос и записываем ответ.`})]}),(0,S.jsxs)(s,{number:`02`,title:`Пишем README как маршрут запуска`,children:[(0,S.jsx)(o,{children:`Главный результат урока находится в README.md. В нём новичок должен найти следующий шаг и понять, как проверить успех.`}),(0,S.jsx)(`p`,{children:`Сначала откроем существующий README, requirements.txt и, если он используется, requirements-dev.txt. Первый перечисляет основные зависимости проекта, второй может содержать инструменты разработки и тестов. Для установки укажем нужную версию Python и рабочую папку. Команды из README сверяем с настоящими файлами и итогом чистой проверки проекта: имя модуля CLI или путь FastAPI нельзя угадывать по названию проекта.`}),(0,S.jsx)(`p`,{children:`README должен объяснять порядок: создать чистое окружение, установить зависимости, запустить CLI, запустить API, открыть документацию, выполнить тесты. CLI означает текстовый интерфейс в терминале. Uvicorn запускает HTTP-сервер с FastAPI. Адрес /docs открывает интерактивную документацию, а /openapi.json возвращает описание маршрутов в JSON. Важно указать локальный адрес сервера и из какой папки вводить команды. Чем установка зависимостей отличается от выполнения тестов? Посмотрим на пример, а точные команды Planner возьмём из его файлов.`}),(0,S.jsx)(x,{caption:`Пример команд для проекта с двумя файлами зависимостей`,code:`python -m pip install -r requirements.txt
python -m pip install -r requirements-dev.txt
python -m pytest`}),(0,S.jsx)(`p`,{children:`Первые две команды устанавливают перечисленные пакеты в выбранный Python, последняя выполняет тесты. Сами по себе эти три строки не запускают сервер или CLI. Если в целевой версии нет второго файла, не включаем вымышленную команду. Если тестам требуется другая команда, записываем проверенную. После запуска сохраняем фактический итог, не обещаем заранее конкретное число passed.`}),(0,S.jsx)(h,{prompt:`Свяжем строку README с тем результатом, который она позволяет увидеть.`,leftTitle:`Что делает читатель`,rightTitle:`Что проверяет`,pairs:[{left:`Устанавливает requirements`,right:`Нужные пакеты доступны выбранному Python`},{left:`Открывает /docs`,right:`Работающий сервер отдаёт страницу документации`},{left:`Запускает python -m pytest`,right:`Выполняются имеющиеся автоматические тесты`},{left:`Запускает CLI`,right:`Текстовые команды доступны через терминал`}],explanation:`Каждая команда подтверждает только своё действие. Просмотр /docs не доказывает, что работают все операции API.`}),(0,S.jsx)(`p`,{children:`Отдельный раздел README описывает, что умеет текущий Planner: знакомые операции CLI и восемь HTTP-операций, без обещаний новых маршрутов. Сверяем их с фактическим API, а не переписываем из будущего плана. Данные пока лежат в локальном JSON-файле, который используют CLI и API. Файл может сохранять задачи между запусками, но одновременная запись двух процессов в один JSON небезопасна: одно изменение может затереть другое.`}),(0,S.jsx)(`p`,{children:`Укажем, где ожидается файл данных и как он появляется после создания задачи, не прикладывая свой личный JSON. Поясним, что 127.0.0.1 относится к этому компьютеру, а не к доступному из интернета сервису. Не называем JSON базой SQL, не обещаем авторизацию, многопользовательскую работу или развёртывание. Эти ограничения так же важны для передачи проекта, как команды запуска.`}),(0,S.jsx)(n,{code:`Журнал проверки проекта: pytest = результат не найден; Postman = не проверен
README: «135 тестов прошли, все запросы в Postman работают»`,question:`Почему такую фразу нельзя оставить в README?`,options:[`Утверждения о тестах и Postman не подтверждены для выбранного SHA.`,`Указывать результаты проверок в README запрещено.`,`Успешная установка зависимостей уже подтверждает Postman.`],correctIndex:0,explanation:`Нужен фактический вывод соответствующего запуска именно для этого SHA. Без него убираем неподтверждённые числа и обещания.`,fix:`Тесты: выполнить команду из README и записать фактический итог.
Postman: не проверен в этой копии.`})]}),(0,S.jsxs)(s,{number:`03`,title:`Проверяем каждое обещание README`,children:[(0,S.jsx)(o,{children:`Исправленный текст ещё не означает, что по нему можно установить проект. Проверим команды своими руками.`}),(0,S.jsx)(`p`,{children:`Для каждой строки README запишем три вещи: что выполняем, какой результат ожидаем и что увидели на самом деле. Например, команда запуска сервера должна завершиться работающим Uvicorn, после чего /docs и /openapi.json должны открываться по указанному адресу. Отдельно пробуем CLI и тесты. Если команда ошибочна, исправляем её в README и повторяем. Нельзя скрывать пропущенный ручной шаг фразой «проверено».`}),(0,S.jsx)(`p`,{children:`В качестве справочника можно открыть docs/test-matrix.md и посмотреть, что именно подтверждают имеющиеся тесты. Например, проверка кода ответа 200 не доказывает сохранение задачи на диск; для этого тест должен проверить данные после записи. Но исправлять матрицу, писать новые тесты или обновлять release notes ради этой практики необязательно. Наша обязательная работа касается инструкций README и их воспроизведения.`}),(0,S.jsx)(u,{question:`Тест с TestClient прошёл, но запрос к запущенному серверу ещё не выполняли. Что можно написать?`,options:[`HTTP-сервер проверен во всех режимах.`,`Автоматический тест прошёл; запуск Uvicorn и внешний запрос пока не проверены.`,`Сценарий Postman тоже прошёл.`],correctIndex:1,explanation:`В отчёте сохраняем границы свидетельства: внутренний тест, работа сервера и Postman являются разными проверками.`}),(0,S.jsx)(`p`,{children:`Для дополнительной сверки пригодятся и экспорты Postman. Коллекция хранит запросы, среда Local задаёт адрес через переменную base_url. Наличие этих JSON-файлов ещё не означает, что запросы отправили. Если сценарий не запускали, так и укажем; токены и личные данные в документы не переносим. Черновик release notes также может помочь сверить ограничения версии, но он не заменяет проверку README.`}),(0,S.jsx)(`p`,{children:`Есть важная последовательность: окончательный README сначала сохраняют в commit, потом проверяют именно этот снимок в отдельном чистом checkout. Иначе мы проверим локальные правки, которые не вошли в версию. Новую копию создаём без старой .venv и случайных локальных файлов, устанавливаем зависимости по инструкции и повторяем все обязательные команды. Если шаг не сработал, исправляем причину, сохраняем новый commit и снова проверяем уже его.`}),(0,S.jsx)(_,{title:`Проверяем воспроизводимость`,label:`ПОРЯДОК ДЕЙСТВИЙ`,prompt:`Выбери порядок, после которого можно честно назвать README проверенным.`,pieces:[{id:`verify`,code:`Повторить README в отдельном чистом checkout итогового commit`},{id:`read`,code:`Сверить SHA и фактические результаты чистой проверки проекта`},{id:`tag`,code:`Проверить и создать локальный API-тег`},{id:`edit`,code:`Исправить README по реальным командам`},{id:`commit`,code:`Сохранить проверяемый README в commit`}],correctOrder:[`read`,`edit`,`commit`,`verify`,`tag`],explanation:`Тег ставим последним, когда есть commit с инструкцией и доказательство, что другой чистый checkout повторяет её.`,incorrectExplanation:`После редактирования нужен commit, после commit проверка его чистой копии. Тег следует только за успешной проверкой.`}),(0,S.jsx)(r,{tone:`info`,children:`Если SHA или результаты чистой проверки проекта отсутствуют, можно подготовить README и найти ошибки, но нельзя объявить исходную проверку успешной или закрепить неподтверждённую версию.`})]}),(0,S.jsxs)(s,{number:`04`,title:`Закрепляем только проверенный commit`,children:[(0,S.jsx)(o,{children:`Когда README уже проверен в новой чистой копии, свяжем локальное имя версии с точным сохранённым состоянием.`}),(0,S.jsx)(`p`,{children:`После правки README сначала проверяем, что изменилось. Git commit сохраняет выбранные файлы под новым SHA. Если README уже был правильным и ничего не меняли, новый commit не нужен, но инструкции всё равно придётся повторить. Ни исходный SHA чистой проверки, ни появившийся после правки SHA нельзя назвать проверенными только по факту сохранения.`}),(0,S.jsx)(`p`,{children:`Перед сохранением смотрим git status --short: какие файлы изменились и нет ли личных данных. Добавляем только README.md, сверяем содержимое подготовленного изменения и делаем commit. Затем запоминаем его новый полный SHA. Если вместе с документацией изменился код или зависимости, нужны и соответствующие повторные проверки. В этом уроке менять исходники Planner не требуется. Какие команды сохранят только исправленную инструкцию?`}),(0,S.jsx)(x,{caption:`Если README действительно изменился`,code:`git status --short
git add README.md
git diff --cached -- README.md
git commit -m "docs: verify Planner API README"
git rev-parse HEAD`}),(0,S.jsx)(`p`,{children:`Команда diff --cached позволяет увидеть, что войдёт в commit. После сохранения открываем отдельную чистую копию именно нового SHA. Строго следуем README: установка из пустого окружения, CLI, Uvicorn, документация и тесты. Записываем реальные результаты. Если проверка не прошла, корректируем README, создаём следующий commit и повторяем затронутые шаги. Для версии подходит только окончательный SHA с воспроизводимой инструкцией.`}),(0,S.jsx)(`p`,{children:`Git tag присваивает commit короткое имя. Это как закладка в конкретном издании: её можно найти, но сама закладка не доказывает правильность содержания. В проекте уже может быть отдельный тег v1.0.0 для CLI; его нельзя занимать или переставлять ради API. GitHub Release является публикацией описания версии, а push отправляет локальные объекты в удалённый репозиторий. Сейчас ни публикация, ни push не нужны. Как проверить имя API-тега до создания и убедиться, что старый тег CLI остаётся на месте?`}),(0,S.jsx)(x,{caption:`Сначала читаем локальные теги`,code:`git status --short
git rev-parse HEAD
git tag --list
git rev-parse "v1.0.0^{commit}"
git rev-parse --verify "refs/tags/planner-api-v1.0.0^{commit}"`}),(0,S.jsx)(`p`,{children:`Здесь status должен быть пустым, а HEAD равен только что проверенному SHA. Список покажет занятые имена. Команда rev-parse с refs/tags проверяет точную цель API-тега; если он отсутствует, Git вернёт ошибку, и это нормально для свободного имени. Если он существует и уже указывает на нужный SHA, повторно создавать ничего не надо. Если он ведёт на другой commit, не перемещаем его и отмечаем конфликт.`}),(0,S.jsx)(l,{question:`Как поставить локальную версию API на подтверждённый SHA?`,left:{title:`Занять тег CLI`,code:`git tag -f v1.0.0 <sha>`,note:`Команда переставит прежнюю метку CLI на другой commit. Такой результат здесь недопустим.`},right:{title:`Создать свободный API-тег`,code:`git tag -a planner-api-v1.0.0 <SHA> -m "Planner API v1.0.0"`,note:`Только если имя свободно, а SHA относится к финальному проверенному commit с README.`},preferred:`right`,explanation:`Не используем -f и не меняем v1.0.0. После создания сверяем git rev-parse "refs/tags/planner-api-v1.0.0^{commit}" с проверенным SHA.`}),(0,S.jsx)(v,{question:`README изменился после чистой проверки проекта. К какому commit нужно привязать API-тег?`,hint:`Подумай, какой снимок содержит итоговые команды и где они были воспроизведены.`,answer:`К окончательному commit с обновлённым README, команды которого мы самостоятельно повторили в отдельном чистом checkout. Исходный SHA проверки остаётся историческим свидетельством, а не целью тега после правки.`})]}),(0,S.jsxs)(s,{number:`05`,title:`Передаём тот же Planner в главу 4`,children:[(0,S.jsx)(o,{children:`Результат этой работы виден другому человеку: он может повторить инструкцию и понять, какую версию получил.`}),(0,S.jsx)(g,{caption:`Как новая версия становится воспроизводимой`,orientation:`vertical`,children:(0,S.jsxs)(m,{label:`От исходных фактов к передаче`,orientation:`vertical`,children:[(0,S.jsx)(f,{title:`Чистая проверка`,children:`Исходный SHA и реальные результаты`}),(0,S.jsx)(p,{label:`сверяем`}),(0,S.jsx)(f,{title:`README в итоговом commit`,children:`Установка, CLI, API, тесты и ограничения JSON`}),(0,S.jsx)(p,{label:`повторяем с нуля`}),(0,S.jsx)(f,{title:`Чистый checkout итогового SHA`,children:`Реальные результаты каждой команды README`}),(0,S.jsx)(p,{label:`помечаем локально`}),(0,S.jsx)(f,{title:`API-тег и глава 4`,children:`Тот же Planner с CLI, FastAPI и JSON`})]})}),(0,S.jsx)(`p`,{children:`Выполним финальную мысленную проверку: новый читатель знает, где корень проекта, какой Python нужен, как поставить зависимости, где запускаются CLI и сервер, как открыть /docs и /openapi.json и как выполнить тесты. Ему не нужно догадываться, почему данные находятся в JSON и почему не стоит писать в файл параллельно из двух процессов. Если хоть один шаг требует устного объяснения, README ещё нужно уточнить.`}),(0,S.jsx)(`p`,{children:`В главе 4 сначала упорядочат существующие модули API и настройки: клиент продолжит обращаться к прежним URL и получать знакомый JSON. SQLite и SQLAlchemy появятся позже. Сейчас мы передаём готовую проверяемую инструкцию и тот же Planner с файловым хранением, без нового CRUD, авторизации и внешней публикации. Это точка, с которой можно безопасно начать следующий этап.`})]}),(0,S.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,S.jsx)(o,{children:`Четыре действия в существующем проекте приведут к README, который можно проверить без подсказок.`}),(0,S.jsx)(d,{variant:`connected`,items:[{title:`1. Установить вход`,description:`Найти SHA и реальные результаты чистой проверки; не выдавать план за подтверждение.`},{title:`2. Обновить README`,description:`Исправить команды установки, CLI/API, тестов и описание JSON.`},{title:`3. Проверить с нуля`,description:`Сохранить README и повторить команды из чистой копии итогового commit.`},{title:`4. Закрепить версию`,description:`Привязать свободный API-тег только к проверенному SHA.`}]}),(0,S.jsx)(`p`,{children:`В практике меняем существующий README, а не создаём новый API или тесты. Если факты чистой проверки отсутствуют, можно подготовить точную инструкцию, но привязку проверенной версии откладываем до получения свидетельств. При успехе итогом будут README с воспроизводимыми шагами и локальный API-тег на тот самый commit.`})]})]})}export{C as Lesson60_1};